const body = $json.body ?? {};
const allowedBodyFields = new Set(['targetLanguage', 'texts']);
const unexpectedFields = Object.keys(body).filter((key) => !allowedBodyFields.has(key));
if (unexpectedFields.length > 0) {
  throw new Error(`Only text translation is allowed. Unexpected fields: ${unexpectedFields.join(', ')}`);
}

const supportedLanguages = new Set(['vi', 'en', 'ja', 'ko', 'zh', 'fr', 'de', 'es', 'th', 'id']);
const targetLanguage = String(body.targetLanguage ?? '').trim().toLowerCase();
if (!supportedLanguages.has(targetLanguage)) {
  throw new Error('Unsupported target language.');
}

if (!Array.isArray(body.texts) || body.texts.length === 0 || body.texts.length > 250) {
  throw new Error('texts must contain between 1 and 250 text items.');
}

const seenKeys = new Set();
let totalCharacters = 0;
const texts = body.texts.map((item) => {
  const key = String(item?.key ?? '').trim();
  const value = String(item?.value ?? '').trim();
  if (!key || key.length > 200 || seenKeys.has(key)) {
    throw new Error('Each text item must have a unique key of at most 200 characters.');
  }
  if (!value || value.length > 5000) {
    throw new Error('Each text value must contain between 1 and 5000 characters.');
  }
  seenKeys.add(key);
  totalCharacters += value.length;
  return { key, value };
});

if (totalCharacters > 30000) {
  throw new Error('The translation request exceeds 30000 characters.');
}

return [{ json: {
  targetLanguage,
  keys: texts.map((item) => item.key),
  sourceTexts: texts.map((item) => item.value)
} }];

const request = $('Validate text-only payload').first().json;
const translated = Array.isArray($json.translatedText)
  ? $json.translatedText
  : [$json.translatedText];

if (translated.length !== request.keys.length) {
  throw new Error('Translation provider returned an unexpected number of items.');
}

return [{ json: {
  targetLanguage: request.targetLanguage,
  items: request.keys.map((key, index) => ({
    key,
    value: String(translated[index] ?? request.sourceTexts[index])
  }))
} }];
